 draw();$('#q').oninput=draw;
 if($('#fl')){const saved=prefGet(k+'_filter',k==='appointments'?'todos':m.flt.o[0][0]);$('#fl').value=m.flt.o.some(o=>o[0]===saved)?saved:(k==='appointments'?'todos':m.flt.o[0][0]);$('#fl').onchange=async()=>{await prefSet(k+'_filter',$('#fl').value);draw()}}
 if(k==='finance'){const fd=$('#fd'),savedDate=prefGet('finance_date',today());fd.value=savedDate;fd.onchange=async()=>{await prefSet('finance_date',fd.value);draw()};$('#fh').onclick=async()=>{fd.value=today();await prefSet('finance_date',fd.value);draw()};$('#fy').onclick=async()=>{fd.value=iso(new Date(Date.now()-864e5));await prefSet('finance_date',fd.value);draw()};$('#fa').onclick=async()=>{fd.value='';await prefSet('finance_date','');draw()}}
