const SYNB=()=>[...document.querySelectorAll('#sync,#syncm')],SYNL=busy=>SYNB().forEach(b=>{b.disabled=busy;b.classList.toggle('busy',busy);if(b.id==='sync')b.innerHTML=busy?'<span class=si>⏳</span><span class=st> Sincronizando...</span>':'<span class=si>🔄</span><span class=st> Sincronizar Dados</span>';else b.textContent=busy?'⏳':'🔄'});
const syncCursorKey=()=>`bp_sync_cursor_${window.TENANT_ID||'local'}_${LOJA}`;
