async function syncRun(silent){SYNL(true);
 try{
  await flush(!silent);
  // Cada aba mantém seu próprio cursor: uma aba não avança a sincronização da outra.
  // A janela de segurança de 10s evita perder alterações em gravações concorrentes.
  const cursor=syncCursorGet(),since=Math.max(0,cursor-10000);
  const j=await api('GET',null,!silent,'?loja='+LOJA+'&since='+since),R=j.records||[],m={};
  window.__NEXUS_SERVICE_HISTORY=R.some(r=>r.store===sn('services'))||C.services.length>0;
  R.forEach(r=>m[r.store+'/'+r.id]=r);
  // Na primeira sincronização (cursor zero), reconcilia o cache local com o conjunto completo.
  // Nas seguintes, as alterações locais já são enviadas pela fila e o servidor retorna somente deltas.
  if(!cursor){
   const up=[];
   for(const s of SYN)for(const o of C[s]){
    if(pendingDel(s,o.id))continue;
    const r=m[sn(s)+'/'+o.id];
    if(s==='settings'&&stPristine(o))continue;
    if(!r||(o._u||0)>r.updated){
     if(!o._u){o._u=Date.now();await put(s,o,1)}
     up.push(rec(s,o));
    }
   }
   if(up.length)await api('POST',{records:up},!silent);
  }
  let ch=0;
  for(const r of R){
   const bs=r.store.split('@')[0];
   if(!SYN.includes(bs)||sn(bs)!==r.store)continue;
   const l=C[bs].find(x=>x.id===r.id);
   if(pendingDel(bs,r.id))continue;
   if(r.deleted){if(l){await del(bs,r.id,1);ch++}continue}
   if(l&&(l._u||0)>=r.updated&&!(bs==='settings'&&stPristine(l)))continue;
   await put(bs,{...JSON.parse(r.data),_u:r.updated},1);ch++;
  }
  // Reenvia exclusões pendentes depois da leitura para neutralizar qualquer resposta antiga em voo.
  await flush(!silent);
  // O servidor devolve seu relógio; mantém sobreposição para cobrir gravações durante a consulta.
  if(Number.isFinite(Number(j.now)))syncCursorSet(Math.max(0,Number(j.now)-10000));
  const i=$('#syncinfo');if(i)i.textContent='Última sincronização: '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
  if(ch&&rdy){brand();if(!document.activeElement||!/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)&&$('#modal').hidden)go(location.hash.slice(1))}
  if(!silent)toast(ch?`Sincronizado: ${ch} registro(s) atualizado(s).`:'Tudo atualizado.')}
 catch(e){if(!silent)toast('Falha ao sincronizar: '+e.message,1)}
 finally{SYNL(false)}}
