const zapNum=c=>{const n=((c&&(c.wpp||c.phone))||'').replace(/\D/g,'');return n?(n.length<=11?'55'+n:n):''};
const isMob=()=>/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)||(/Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1);
document.body.classList.toggle('desk',!isMob()); // computador: só "Copiar" (abrir o WhatsApp Web toda vez abre página nova e recarrega)
const copyTxt=async t=>{try{await navigator.clipboard.writeText(t);return true}catch{const a=document.createElement('textarea');a.value=t;a.style.cssText='position:fixed;opacity:0';document.body.appendChild(a);a.select();let ok=false;try{ok=document.execCommand('copy')}catch{}a.remove();return ok}};
// Celular: abre o app do WhatsApp com a mensagem pronta. Computador: copia a mensagem para colar no WhatsApp já aberto.
const zapOpen=(full,t)=>{if(!isMob()){copyTxt(t).then(ok=>ok?toast('Mensagem copiada! Cole no WhatsApp do cliente.'):prompt('Copie a mensagem:',t));return}copyTxt(t);window.open(`https://api.whatsapp.com/send?phone=${full}&text=${encodeURIComponent(t)}&app_absent=0`,'_blank')};
const zapPref=()=>'',zapPrefBind=()=>{};
const remList=()=>{const t=today(),tm=iso(new Date(Date.now()+864e5)),hm=new Date().toTimeString().slice(0,5);return C.appointments.filter(a=>['aguardando','confirmado'].includes(a.status)&&(a.date===tm||(a.date===t&&String(a.time||'')>=hm))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))};
const remPend=()=>remList().filter(a=>!a.rem).length;
function remMenu(done){const t=today(),s=S(),m=$('#modal');
 const msg=a=>{const c=C.clients.find(x=>x.id===a.client)||{},nome=(c.name||'').split(' ')[0]||'tudo bem',svc=nm('services',a.service),bb=nm('barbers',a.barber),quando=a.date===t?'hoje':'amanhã ('+br(a.date)+')';return `Olá, ${nome}! Passando para lembrar do seu horário na ${s.name}: ${quando} às ${a.time}${svc?' — '+svc:''}${bb?' com '+bb:''}.${s.address?' Endereço: '+s.address+'.':''} Podemos confirmar? Qualquer imprevisto, é só avisar. 💈`};
 const row=a=>{const c=C.clients.find(x=>x.id===a.client)||{},ok=!!a.rem,num=zapNum(c);return `<div class="rem-row${ok?' sent':''}"><div class=rem-i><b>${esc(a.time)}</b> ${esc(c.name||'Cliente')}<small class=mu>${esc(nm('services',a.service)||'')}${a.barber?' · '+esc(nm('barbers',a.barber)):''}${ok?' · ✅ lembrete enviado':''}${num?'':' · sem telefone'}</small></div>${num?`<span class=rem-b><button class="btn g copy-main" data-remc=${a.id} title="Copiar mensagem">📋 Copiar</button><button class="btn${ok?' g':''} mob-only" data-rem=${a.id}>${ok?'Reenviar':'💬 Enviar'}</button></span>`:''}</div>`};
 const draw=()=>{const L=remList(),hj=L.filter(a=>a.date===t),am=L.filter(a=>a.date!==t),sec=(tt,l)=>`<h4 class=rem-h>${tt} <small class=mu>(${l.length})</small></h4>${l.length?l.map(row).join(''):'<div class=mu style="padding:4px 0 8px">Nenhum horário.</div>'}`;
  m.innerHTML=`<div class="card rem-card"><h3>🔔 Lembretes dos clientes</h3><p class=mu>${isMob()?'Toque em <b>Enviar</b>: o WhatsApp abre com a mensagem pronta para o cliente. Prefere colar você mesmo? Use <b>Copiar</b>.':'Clique em <b>Copiar</b> e cole a mensagem no WhatsApp do cliente.'} O horário fica marcado aqui.</p>${zapPref()}${sec('Hoje',hj)}${sec('Amanhã',am)}<button class="btn g" id=rcx style="width:100%;margin-top:10px">Fechar</button></div>`;
  $('#rcx').onclick=()=>{m.hidden=true;done&&done()};zapPrefBind()};
 m.hidden=false;draw();
 m.onclick=async e=>{const cp=e.target.closest('[data-remc]');if(cp){const a=C.appointments.find(x=>x.id===cp.dataset.remc);if(!a)return;await copyTxt(msg(a));toast('Mensagem copiada! Cole no WhatsApp do cliente.');await put('appointments',{...a,rem:Date.now()});draw();return}const b=e.target.closest('[data-rem]');if(b){const a=C.appointments.find(x=>x.id===b.dataset.rem);if(!a)return;const c=C.clients.find(x=>x.id===a.client)||{};zapOpen(zapNum(c),msg(a));await put('appointments',{...a,rem:Date.now()});draw();return}if(e.target.id==='modal'){m.hidden=true;done&&done()}}}
const sumDays=60,lastVisit=id=>vis(id).map(a=>a.date).sort().pop()||'';
const sumList=()=>{const t=today();return C.clients.map(c=>({c,lv:lastVisit(c.id)})).filter(x=>x.lv&&(Date.now()-new Date(x.lv))/864e5>sumDays&&!C.appointments.some(a=>a.client===x.c.id&&a.date>=t&&['aguardando','confirmado'].includes(a.status))).sort((a,b)=>a.lv.localeCompare(b.lv))};
function sumMsg(c){const s=S(),nome=(c.name||'').split(' ')[0]||'tudo bem';return `Olá, ${nome}! Aqui é da ${s.name}. Faz um tempinho que você não aparece e sentimos sua falta! 😊 Que tal agendar um horário esta semana? É só responder esta mensagem que a gente encaixa você. 💈`}
function sumMenu(done){const m=$('#modal');
 const draw=()=>{const L=sumList();m.innerHTML=`<div class="card rem-card"><h3>💬 Clientes sumidos</h3><p class=mu>Clientes que não vêm há mais de ${sumDays} dias e não têm horário marcado. ${isMob()?'Toque em <b>Chamar</b> para abrir o WhatsApp com um convite pronto para voltar, ou em <b>Copiar</b> para colar você mesmo.':'Clique em <b>Copiar</b> e cole o convite no WhatsApp do cliente.'}</p>${zapPref()}${L.length?L.map(({c,lv})=>{const d=Math.floor((Date.now()-new Date(lv))/864e5),num=zapNum(c),ch=c.back?new Date(c.back).toLocaleDateString('pt-BR'):'';return `<div class="rem-row${ch?' sent':''}"><div class=rem-i><b>${esc(c.name)}</b><small class=mu>Última visita ${br(lv)} · há ${d} dias${ch?' · ✅ chamado em '+ch:''}${num?'':' · sem telefone'}</small></div>${num?`<span class=rem-b><button class="btn g copy-main" data-sumc=${c.id} title="Copiar mensagem">📋 Copiar</button><button class="btn${ch?' g':''} mob-only" data-sum=${c.id}>${ch?'Chamar de novo':'💬 Chamar'}</button></span>`:''}</div>`}).join(''):'<div class=empty>Nenhum cliente sumido. 🎉</div>'}<button class="btn g" id=rcx style="width:100%;margin-top:10px">Fechar</button></div>`;
  $('#rcx').onclick=()=>{m.hidden=true;done&&done()};zapPrefBind()};
 m.hidden=false;draw();
 m.onclick=async e=>{const cp=e.target.closest('[data-sumc]');if(cp){const c=C.clients.find(x=>x.id===cp.dataset.sumc);if(!c)return;await copyTxt(sumMsg(c));toast('Mensagem copiada! Cole no WhatsApp do cliente.');await put('clients',{...c,back:Date.now()});draw();return}const b=e.target.closest('[data-sum]');if(b){const c=C.clients.find(x=>x.id===b.dataset.sum);if(!c)return;zapOpen(zapNum(c),sumMsg(c));await put('clients',{...c,back:Date.now()});draw();return}if(e.target.id==='modal'){m.hidden=true;done&&done()}}}
function cliZap(id){const c=C.clients.find(x=>x.id===id);if(!c)return;const num=zapNum(c);if(!num)return toast('Cadastre o WhatsApp ou telefone deste cliente.',1);const lv=lastVisit(id),out=lv&&(Date.now()-new Date(lv))/864e5>sumDays;
 if(out){zapOpen(num,sumMsg(c));put('clients',{...c,back:Date.now()}).catch(()=>{});return}
 const s=S(),nome=(c.name||'').split(' ')[0]||'tudo bem';zapOpen(num,`Olá, ${nome}! Aqui é da ${s.name}. 💈`)}

function wppMenu(id){const a=C.appointments.find(x=>x.id===id),c=C.clients.find(x=>x.id===a.client)||{},s=S(),nome=(c.name||'cliente').split(' ')[0],emp=s.name,d=br(a.date),svc=nm('services',a.service),bb=nm('barbers',a.barber);
 const num=((c.wpp||c.phone)||'').replace(/\D/g,'');if(!num)return toast('Cadastre o WhatsApp ou telefone deste cliente.',1);const full=num.length<=11?'55'+num:num;
 const MSG=[['🙏 Agradecimento',`Olá, ${nome}! Muito obrigado pela visita à ${emp}. Foi um prazer atender você! Volte sempre. 💈`],['✅ Confirmar agendamento',`Olá, ${nome}! Seu horário na ${emp} está agendado: ${svc} com ${bb} em ${d} às ${a.time}.${s.address?' Endereço: '+s.address+'.':''} Podemos confirmar? 👍`],['⏰ Estamos aguardando você',`Olá, ${nome}! Estamos te aguardando hoje às ${a.time} na ${emp}. Até já! 💈`],['🔔 Lembrete do horário',`Olá, ${nome}! Lembrando do seu horário na ${emp}: ${d} às ${a.time} (${svc}). Qualquer imprevisto, é só avisar.`],['🔄 Remarcar',`Olá, ${nome}! Precisamos remarcar seu horário de ${d} às ${a.time} na ${emp}. Qual o melhor dia e horário para você?`]];
 $('#modal').hidden=false;$('#modal').innerHTML=`<div class=card><h3>Mensagem para ${esc(c.name||'cliente')}</h3>${MSG.map((m,i)=>`<div class="mrow w"><button class="btn g" data-i=${i}>${m[0]}</button><button class="btn g" data-c=${i} title="Copiar mensagem">📋 Copiar</button><button class="btn g mob-only" data-i=${i} title="Abrir no WhatsApp">💬 WhatsApp</button></div>`).join('')}<button class="btn g" id=cx>Fechar</button></div>`;
 $('#cx').onclick=()=>$('#modal').hidden=true;
 $('#modal').onclick=async e=>{const cb=e.target.closest('[data-c]');if(cb){const t=MSG[cb.dataset.c][1];try{await navigator.clipboard.writeText(t)}catch{const a=document.createElement('textarea');a.value=t;a.style.cssText='position:fixed;opacity:0';document.body.appendChild(a);a.select();try{document.execCommand('copy')}catch{}a.remove()}toast('Mensagem copiada! Cole no WhatsApp Web.');cb.textContent='✅ Copiado';setTimeout(()=>{cb.textContent='📋 Copiar'},1800);return}const b=e.target.closest('[data-i]');if(b){const t=MSG[b.dataset.i][1];zapOpen(full,t);$('#modal').hidden=true}else if(e.target.id==='modal')e.target.hidden=true}}

