/* ---------- Fim do teste / licença vencida com o painel aberto ----------
   O servidor recusa salvar quando a licença vence (HTTP 402). Assim que isso acontece — ou quando a verificação
   periódica percebe o vencimento — uma tela cobre o painel e leva para a escolha do plano. Os dados ficam guardados. */
let LIC_LOCK=false;
function licencaBloqueada(info){if(LIC_LOCK)return;LIC_LOCK=true;
 const susp=(info&&info.status==='suspended')||/suspens/i.test(String(info?.error||'')),trial=window.TENANT?.tenant?.status==='trial'||(window.TENANT?.tenant?.trial_expires_at&&!window.TENANT?.tenant?.license_expires_at);
 const o=document.createElement('div');o.id='licLock';o.setAttribute('role','alertdialog');o.setAttribute('aria-modal','true');
 o.innerHTML=`<div class=lic-box><div class=lic-ic>${susp?'⛔':'⏰'}</div><h2>${susp?'Conta suspensa':trial?'Seu período de teste terminou':'Sua licença venceu'}</h2>
 <p>${susp?'O acesso ao painel foi suspenso. Fale com o suporte para regularizar.':'Para continuar usando o sistema, escolha um plano. <b>Seus dados estão guardados</b> — clientes, agenda, caixa e financeiro voltam assim que o pagamento for confirmado.'}</p>
 <div class=lic-act>${susp?'':'<a class=btn href="/app.html">💳 Escolher plano</a>'}<a class="btn g" href="/app.html">Minha conta</a></div>
 <small class=mu>Lançamentos feitos agora não seriam salvos, por isso o painel foi pausado.</small></div>`;
 document.body.append(o);document.body.classList.add('lic-locked');try{document.activeElement?.blur()}catch{}}
// Verificação leve: ao voltar para a aba, a cada 5 min e no horário exato do vencimento.
(()=>{const chk=async()=>{if(LIC_LOCK||!navigator.onLine)return;try{const r=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'}),j=await r.json();if(j&&j.blocked)licencaBloqueada({status:j.tenant?.status})}catch{}};
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)chk()});setInterval(chk,5*6e4);
 try{const end=new Date(window.TENANT?.expires_at||0).getTime(),ms=end-Date.now();if(end&&ms>0&&ms<2147e6)setTimeout(chk,ms+5000);else if(end&&ms<=0)chk()}catch{}})();

/* ---------- Janelas: botão ✕ no canto; toque fora NÃO fecha mais (o ✕ pisca para indicar como sair) ---------- */
(()=>{const m=document.getElementById('modal');if(!m)return;
 const fechar=()=>{const h=m.onclick;if(typeof h==='function'){try{h.call(m,{target:m,currentTarget:m,preventDefault(){},stopPropagation(){}})}catch{}}if(!m.hidden)m.hidden=true};
 const addX=()=>{if(m.hidden)return;const c=m.firstElementChild;if(!c||c.classList.contains('tour-card')||c.querySelector(':scope>.mx'))return;
  if(typeof m.onclick!=='function')return; // janela que não pode ser fechada agora (ex.: cobrança em andamento na maquininha)
  const b=document.createElement('button');b.type='button';b.className='mx';b.setAttribute('aria-label','Fechar');b.title='Fechar';b.textContent='✕';
  b.onclick=e=>{e.preventDefault();e.stopPropagation();fechar()};c.prepend(b)};
 new MutationObserver(()=>setTimeout(addX,0)).observe(m,{childList:true,attributes:true,attributeFilter:['hidden']});
 document.addEventListener('click',e=>{if(e.target!==m||m.hidden)return;e.stopPropagation();e.preventDefault();
  const x=m.querySelector('.mx');if(x){x.classList.remove('mxp');void x.offsetWidth;x.classList.add('mxp')}},true);
})();
